// Page Table Entry (PTE) Structure - Hardware Abstraction
// Defines how virtual addresses map to physical frames,
// enforcing protection and residency.

typedef unsigned long uint64_t; // 64-bit entry size

struct PageTableEntry {
    uint64_t Present : 1;      // V/R: Is page resident in RAM?
    uint64_t R_W : 1;          // RW: Read/Write permissions
    uint64_t User_Sup : 1;     // US: Protection boundary (Security)
    uint64_t Accessed : 1;     // A: Used recently?
    uint64_t Dirty : 1;        // D: Has data been written?
    uint64_t Reserved : 7;
    uint64_t PhysicalFrame : 40; // PFN (Physical Frame Number) Base Address
    uint64_t Ignored : 11;
    uint64_t NoExecute : 1;    // NX: Prevent code execution (Security)
};

// VAddr = [ Level 4 Index | L3 Index | L2 Index | L1 Index | Offset ]
// Translation: 4 lookups to resolve PFN + 1 offset addition = PAddr.
